1: import { passkey } from "@better-auth/passkey";
2: import { days, minutes, Policy, toSeconds } from "@surveybeat/domain";
3: import { betterAuth } from "better-auth";
4: import type { Auth, BetterAuthOptions, BetterAuthPlugin } from "better-auth";
5: import { memoryAdapter } from "better-auth/adapters/memory";
6: import { admin, emailOTP, magicLink, organization } from "better-auth/plugins";
7: import * as Effect from "effect/Effect";
8: 
9: export const SESSION_COOKIE = "__Host-surveybeat-session";
10: 
11: export const SESSION_TTL_SECONDS = toSeconds(days(Policy.signIn.sessionDays));
12: 
13: export const CODE_TTL_SECONDS = toSeconds(minutes(Policy.signIn.codeMinutes));
14: 
15: export const MAGIC_LINK_TTL_SECONDS = toSeconds(minutes(Policy.signIn.magicLinkMinutes));
16: 
17: export const AUTH_TABLES = {
18:   user: "auth_user",
19:   session: "auth_session",
20:   account: "auth_account",
21:   verification: "auth_verification",
22:   organization: "auth_organization",
23:   member: "auth_member",
24:   invitation: "auth_invitation",
25:   passkey: "auth_passkey",
26: } as const;
27: 
28: export interface AuthSettings {
29:   readonly baseURL: string;
30:   readonly secret: string;
31:   readonly trustedOrigins: readonly string[];
32: }
33: 
34: export interface CodeDelivery {
35:   readonly sendSignInCode: (code: { readonly email: string; readonly otp: string }) => Effect.Effect<void>;
36:   readonly sendEmailChangeCode: (code: {
37:     readonly email: string;
38:     readonly otp: string;
39:   }) => Effect.Effect<void>;
40:   readonly sendMagicLink: (link: { readonly email: string; readonly url: string }) => Effect.Effect<void>;
41: }
42: 
43: export type SurveyBeatAuthOptions = Omit<BetterAuthOptions, "baseURL" | "database" | "secret" | "plugins">;
44: 
45: export const authPlugins = (delivery: CodeDelivery): BetterAuthPlugin[] => [
46:   emailOTP({
47:     otpLength: Policy.signIn.codeDigits,
48:     expiresIn: CODE_TTL_SECONDS,
49:     allowedAttempts: Policy.signIn.codeAttempts,
50:     changeEmail: { enabled: true },
51:     sendVerificationOTP: ({ email, otp, type }) => {
52:       switch (type) {
53:         case "sign-in": {
54:           return Effect.runPromise(delivery.sendSignInCode({ email, otp }));
55:         }
56: 
57:         case "change-email": {
58:           return Effect.runPromise(delivery.sendEmailChangeCode({ email, otp }));
59:         }
60: 
61:         case "email-verification":
62:         case "forget-password": {
63:           return Promise.resolve();
64:         }
65:       }
66:     },
67:   }),
68:   magicLink({
69:     expiresIn: MAGIC_LINK_TTL_SECONDS,
70:     sendMagicLink: ({ email, url }) => Effect.runPromise(delivery.sendMagicLink({ email, url })),
71:   }),
72:   admin({ defaultRole: "user", adminRoles: ["admin"] }),
73:   organization({
74:     allowUserToCreateOrganization: false,
75:     schema: {
76:       organization: { modelName: AUTH_TABLES.organization },
77:       member: { modelName: AUTH_TABLES.member },
78:       invitation: { modelName: AUTH_TABLES.invitation },
79:     },
80:   }),
81:   passkey({
82:     rpName: "SurveyBeat",
83:     schema: { passkey: { modelName: AUTH_TABLES.passkey } },
84:   }),
85: ];
86: 
87: export const authOptions = (
88:   delivery: CodeDelivery,
89: ): SurveyBeatAuthOptions & { plugins: BetterAuthPlugin[] } => ({
90:   appName: "SurveyBeat",
91:   basePath: "/auth",
92:   trustedOrigins: [
93:     "https://surveybeat.app",
94:     "https://*.surveybeat.app",
95:     "http://localhost:5173",
96:     "http://127.0.0.1:5173",
97:   ],
98:   session: {
99:     expiresIn: SESSION_TTL_SECONDS,
100:     updateAge: 24 * 60 * 60,
101:     modelName: AUTH_TABLES.session,
102:   },
103:   user: { modelName: AUTH_TABLES.user },
104:   account: { modelName: AUTH_TABLES.account },
105:   verification: { modelName: AUTH_TABLES.verification },
106:   advanced: {
107:     useSecureCookies: false,
108:     cookies: { session_token: { name: SESSION_COOKIE } },
109:     defaultCookieAttributes: { httpOnly: true, secure: true, sameSite: "lax", path: "/" },
110:   },
111:   plugins: authPlugins(delivery),
112: });
113: 
114: export const createAuth = (params: {
115:   readonly settings: AuthSettings;
116:   readonly delivery: CodeDelivery;
117:   readonly database?: BetterAuthOptions["database"];
118: }): Auth => {
119:   const options: BetterAuthOptions = {
120:     ...authOptions(params.delivery),
121:     baseURL: params.settings.baseURL,
122:     secret: params.settings.secret,
123:     trustedOrigins: [...params.settings.trustedOrigins],
124:     ...(params.database === undefined ? {} : { database: params.database }),
125:   };
126: 
127:   return betterAuth(options);
128: };
129: 
130: export const memoryAuth = (delivery: CodeDelivery): Auth =>
131:   createAuth({
132:     settings: {
133:       baseURL: "http://localhost:5173",
134:       secret: "surveybeat-memory-test-secret-000000000000",
135:       trustedOrigins: ["http://localhost:5173"],
136:     },
137:     delivery,
138:     database: memoryAdapter({
139:       [AUTH_TABLES.account]: [],
140:       [AUTH_TABLES.session]: [],
141:       [AUTH_TABLES.user]: [],
142:       [AUTH_TABLES.verification]: [],
143:       [AUTH_TABLES.organization]: [],
144:       [AUTH_TABLES.member]: [],
145:       [AUTH_TABLES.invitation]: [],
146:       [AUTH_TABLES.passkey]: [],
147:     }),
148:   });

