43: export const requestOrigin = Effect.map(HttpServerRequest, (request) =>
44:   URL.canParse(request.originalUrl)
45:     ? new URL(request.originalUrl).origin
46:     : Option.match(toURL(request), { onNone: () => "http://localhost", onSome: (url) => url.origin }),
