261: interface D1Result<T> {
262:   readonly results: T[];
263:   readonly meta: { readonly changes: number; readonly last_row_id: number };
264: }
265: 
266: interface AuthorizedStatement {
267:   readonly bind: (...values: readonly unknown[]) => AuthorizedStatement;
268:   readonly all: () => Promise<D1Result<unknown>>;
269:   readonly run: () => Promise<unknown>;
270: }
