272: // Better Auth resolves its session rows through a D1-shaped database, so the test hands it Node's
273: // SQLite behind that interface and lets the real migrations run in front of it.
274: const betterAuthDatabase = () => {
275:   const sqlite = new DatabaseSync(":memory:");
276: 
277:   for (const file of readdirSync(migrations).sort()) {
278:     sqlite.exec(readFileSync(new URL(file, migrations), "utf8"));
279:   }
280: 
281:   const bounded = (binds: readonly unknown[]) => binds as (null | number | string)[];
282: 
283:   const statement = (sql: string, binds: readonly unknown[]): AuthorizedStatement => ({
284:     bind: (...values) => statement(sql, values),
285:     run: () => {
286:       sqlite.prepare(sql).run(...bounded(binds));
287: 
288:       return Promise.resolve();
289:     },
290:     all: () => {
291:       const prepared = sqlite.prepare(sql);
292: 
293:       if (prepared.columns().length === 0) {
294:         const applied = prepared.run(...bounded(binds));
295: 
296:         return Promise.resolve({
297:           results: [] as unknown[],
298:           meta: { changes: Number(applied.changes), last_row_id: Number(applied.lastInsertRowid) },
299:         });
300:       }
301: 
302:       return Promise.resolve({
303:         results: prepared.all(...bounded(binds)),
304:         meta: { changes: 0, last_row_id: 0 },
305:       });
306:     },
307:   });
308: 
309:   const database = {
310:     prepare: (sql: string) => statement(sql, []),
311:     batch: (statements: readonly AuthorizedStatement[]) =>
312:       Promise.all(statements.map((query) => query.all())),
313:     exec: (sql: string) => Promise.resolve(sqlite.exec(sql)),
314:   };
315: 
316:   return { sqlite, database };
317: };
