222: export const runApi = <A, M>(
223:   f: (api: ApiClient) => Effect.Effect<A, unknown>,
224:   onSuccess: (value: A) => M,
225:   onFailure: (failure: Failure) => M,
226: ): Effect.Effect<M> => {
227:   const recover = (failure: unknown): Effect.Effect<M> => Effect.succeed(onFailure(failureOf(failure)));
