const ANONYMOUS_AAGUID = "00000000-0000-0000-0000-000000000000";

const COMMON_AUTHENTICATOR_NAMES: Readonly<Record<string, string>> = {
  "ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4": "Google Password Manager",
  "fbfc3007-154e-4ecc-8c0b-6e020557d7bd": "Apple Passwords",
  "dd4ec289-e01d-41c9-bb89-70fa845d4bf2": "iCloud Keychain (Managed)",
  "08987058-cadc-4b81-b6e1-30de50dcbe96": "Windows Hello",
  "9ddd1817-af5a-4672-a2b9-3e3dd95000a9": "Windows Hello",
  "6028b017-b1d4-4c02-b4b3-afcdafc96bb2": "Windows Hello",
  "bada5566-a7aa-401f-bd96-45619a55120d": "1Password",
  "d548826e-79b4-db40-a3d8-11116f7e8349": "Bitwarden",
  "531126d6-e717-415c-9320-3d9aa6981239": "Dashlane",
  "b78a0a55-6ef8-d246-a042-ba0f6d55050c": "LastPass",
  "b84e4048-15dc-4dd0-8640-f4f60813c8af": "NordPass",
  "50726f74-6f6e-5061-7373-50726f746f6e": "Proton Pass",
  "0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6": "Keeper",
  "53414d53-554e-4700-0000-000000000000": "Samsung Pass",
};

export const aaguidProviderName = (aaguid: string | null): string | null => {
  const normalized = aaguid?.trim().toLowerCase();

  if (normalized === undefined || normalized === "" || normalized === ANONYMOUS_AAGUID) {
    return null;
  }

  return COMMON_AUTHENTICATOR_NAMES[normalized] ?? null;
};

const webAuthnStatic = (): ModernPublicKeyCredentialStatic | undefined =>
  typeof window !== "undefined" && typeof PublicKeyCredential === "function" ? PublicKeyCredential : undefined;

export const isValidBase64Url = (value: string): boolean =>
  value.length > 0 && value.length % 4 !== 1 && /^[A-Za-z0-9_-]+$/.test(value);

const fromBase64Url = (value: string): Uint8Array<ArrayBuffer> => {
  const padded = value.replaceAll("-", "+").replaceAll("_", "/").padEnd(Math.ceil(value.length / 4) * 4, "=");
  const binary = atob(padded);
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));

  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.codePointAt(index) ?? 0;
  }

  return bytes;
};

const toBase64Url = (buffer: ArrayBuffer): string => {
  const bytes = new Uint8Array(buffer);
  let binary = "";

  for (const byte of bytes) {
    binary += String.fromCodePoint(byte);
  }

  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
};

const toTransport = (value: string): AuthenticatorTransport | null => {
  switch (value) {
    case "ble":
    case "hybrid":
    case "internal":
    case "nfc":
    case "usb": {
      return value;
    }

    default: {
      return null;
    }
  }
};

const toDescriptor = (item: typeof RawDescriptor.Type): PublicKeyCredentialDescriptor => {
  const transports = (item.transports ?? [])
    .map(toTransport)
    .filter((entry): entry is AuthenticatorTransport => entry !== null);

  return {
    type: item.type,
    id: fromBase64Url(item.id),
    ...(transports.length > 0 ? { transports } : {}),
  };
};

const parseRequestOptions = (raw: unknown): PublicKeyCredentialRequestOptions | null => {
  const api = webAuthnStatic();

  if (api?.parseRequestOptionsFromJSON !== undefined) {
    return api.parseRequestOptionsFromJSON(raw);
  }

  const decoded = Schema.decodeUnknownOption(RawRequestOptions)(raw);

  if (Option.isNone(decoded)) {
    return null;
  }

  const options = decoded.value;

  return {
    challenge: fromBase64Url(options.challenge),
    ...(options.rpId === undefined ? {} : { rpId: options.rpId }),
    ...(options.timeout === undefined ? {} : { timeout: options.timeout }),
    ...(options.userVerification === undefined ? {} : { userVerification: options.userVerification }),
    ...(options.allowCredentials === undefined
      ? {}
      : { allowCredentials: options.allowCredentials.map(toDescriptor) }),
  };
};

const parseCreationOptions = (raw: unknown): PublicKeyCredentialCreationOptions | null => {
  const api = webAuthnStatic();

  if (api?.parseCreationOptionsFromJSON !== undefined) {
    return api.parseCreationOptionsFromJSON(raw);
  }

  const decoded = Schema.decodeUnknownOption(RawCreationOptions)(raw);

  if (Option.isNone(decoded)) {
    return null;
  }

  const options = decoded.value;

  return {
    challenge: fromBase64Url(options.challenge),
    rp: {
      name: options.rp.name,
      ...(options.rp.id === undefined ? {} : { id: options.rp.id }),
    },
    user: {
      id: fromBase64Url(options.user.id),
      name: options.user.name,
      displayName: options.user.displayName,
    },
    pubKeyCredParams: options.pubKeyCredParams.map((param) => ({
      type: param.type,
      alg: param.alg,
    })),
    ...(options.timeout === undefined ? {} : { timeout: options.timeout }),
    ...(options.excludeCredentials === undefined
      ? {}
      : { excludeCredentials: options.excludeCredentials.map(toDescriptor) }),
    ...(options.authenticatorSelection === undefined
      ? {}
      : { authenticatorSelection: { ...options.authenticatorSelection } }),
    ...(options.attestation === undefined ? {} : { attestation: options.attestation }),
  };
};

const serializeCredential = (credential: PublicKeyCredential): unknown => {
  const modern: ModernPublicKeyCredential = credential;

  if (typeof modern.toJSON === "function") {
    return modern.toJSON();
  }

  if (credential.response instanceof AuthenticatorAssertionResponse) {
    return {
      id: credential.id,
      rawId: toBase64Url(credential.rawId),
      type: credential.type,
      authenticatorAttachment: credential.authenticatorAttachment ?? undefined,
      response: {
        clientDataJSON: toBase64Url(credential.response.clientDataJSON),
        authenticatorData: toBase64Url(credential.response.authenticatorData),
        signature: toBase64Url(credential.response.signature),
        ...(credential.response.userHandle === null
          ? {}
          : { userHandle: toBase64Url(credential.response.userHandle) }),
      },
      clientExtensionResults: credential.getClientExtensionResults(),
    };
  }

  if (credential.response instanceof AuthenticatorAttestationResponse) {
    const transports =
      typeof credential.response.getTransports === "function" ? credential.response.getTransports() : [];

    return {
      id: credential.id,
      rawId: toBase64Url(credential.rawId),
      type: credential.type,
      authenticatorAttachment: credential.authenticatorAttachment ?? undefined,
      response: {
        clientDataJSON: toBase64Url(credential.response.clientDataJSON),
        attestationObject: toBase64Url(credential.response.attestationObject),
        transports,
      },
      clientExtensionResults: credential.getClientExtensionResults(),
    };
  }

  return null;
};

const signalUnknownCredentialSafe = async (
  rpId: string | undefined,
  credentialId: string | undefined,
): Promise<void> => {
  const api = webAuthnStatic();

  if (
    api?.signalUnknownCredential === undefined ||
    rpId === undefined ||
    rpId === "" ||
    credentialId === undefined ||
    !isValidBase64Url(credentialId)
  ) {
    return;
  }

  try {
    await api.signalUnknownCredential({ rpId, credentialId });
  } catch (error) {
    console.warn("signalUnknownCredential sync warning:", error);
  }
};

const readErrorCode = async (response: Response): Promise<string | null> => {
  try {
    const body: unknown = await response.json();
    const decoded = Schema.decodeUnknownOption(ErrorPayload)(body);

    return Option.match(decoded, {
      onNone: () => null,
      onSome: (value) => value.code ?? null,
    });
  } catch {
    return null;
  }
};

const errorNameOf = (error: unknown): string => {
  if (typeof error === "object" && error !== null && "name" in error && typeof error.name === "string") {
    return error.name;
  }

  return "";
};

const isoStringOf = (value: string | number | null | undefined): string | null => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  return Option.match(DateTime.make(value), {
    onNone: () => String(value),
    onSome: DateTime.formatIso,
  });
};

export const detectPasskeyCapabilities: Effect.Effect<PasskeyCapabilities> = Effect.promise(async () => {
  const api = webAuthnStatic();

  if (api === undefined || typeof navigator === "undefined" || navigator.credentials === undefined) {
    return defaultPasskeyCapabilities;
  }

  if (typeof api.getClientCapabilities === "function") {
    try {
      const capabilities = await api.getClientCapabilities();
      const conditionalGet = Boolean(capabilities["conditionalGet"]);
      const platformAuthenticator = Boolean(capabilities["passkeyPlatformAuthenticator"]);
      const hybridTransport = Boolean(capabilities["hybridTransport"]);
      const userVerifying = Boolean(capabilities["userVerifyingPlatformAuthenticator"]);

      return {
        supported: conditionalGet || platformAuthenticator || hybridTransport || userVerifying,
        conditionalGet,
        platformAuthenticator,
      };
    } catch {
      return defaultPasskeyCapabilities;
    }
  }

  const platformAuthenticator =
    typeof api.isUserVerifyingPlatformAuthenticatorAvailable === "function"
      ? await api.isUserVerifyingPlatformAuthenticatorAvailable().catch(() => false)
      : false;

  const conditionalGet =
    typeof api.isConditionalMediationAvailable === "function"
      ? await api.isConditionalMediationAvailable().catch(() => false)
      : false;

  return {
    supported: platformAuthenticator || conditionalGet,
    conditionalGet,
    platformAuthenticator,
  };
});

export type PasskeySignInOutcome =
  | { readonly _tag: "Verified" }
  | { readonly _tag: "Cancelled" }
  | { readonly _tag: "Failed" };

export const authenticateWithPasskey = (params: {
  readonly conditional: boolean;
  readonly signal?: AbortSignal | undefined;
}): Effect.Effect<PasskeySignInOutcome> =>
  Effect.promise(async (): Promise<PasskeySignInOutcome> => {
    let optionsJson: unknown;

    try {
      const optionsRes = await fetch("/auth/passkey/generate-authenticate-options", {
        method: "GET",
        credentials: "same-origin",
        ...(params.signal === undefined ? {} : { signal: params.signal }),
      });

      if (!optionsRes.ok) {
        return { _tag: "Failed" };
      }

      optionsJson = await optionsRes.json();
    } catch (error) {
      return errorNameOf(error) === "AbortError" ? { _tag: "Cancelled" } : { _tag: "Failed" };
    }

    const publicKey = parseRequestOptions(optionsJson);

    if (publicKey === null) {
      return { _tag: "Failed" };
    }

    const rpId = Option.match(Schema.decodeUnknownOption(RequestRpPayload)(optionsJson), {
      onNone: () => publicKey.rpId,
      onSome: (parsed) => parsed.rpId ?? publicKey.rpId,
    });

    let credential: Credential | null = null;

    try {
      credential = await navigator.credentials.get({
        publicKey,
        ...(params.conditional ? { mediation: "conditional" } : {}),
        ...(params.signal === undefined ? {} : { signal: params.signal }),
      });
    } catch (error) {
      const name = errorNameOf(error);

      return name === "NotAllowedError" || name === "AbortError" ? { _tag: "Cancelled" } : { _tag: "Failed" };
    }

    if (!(credential instanceof PublicKeyCredential)) {
      return { _tag: "Failed" };
    }

    const encoded = serializeCredential(credential);

    if (encoded === null) {
      return { _tag: "Failed" };
    }

    const encodedId = Option.match(Schema.decodeUnknownOption(EncodedIdPayload)(encoded), {
      onNone: () => undefined,
      onSome: (parsed) => parsed.id,
    });

    try {
      const verifyRes = await fetch("/auth/passkey/verify-authentication", {
        method: "POST",
        headers: { "content-type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({ response: encoded }),
      });

      if (verifyRes.ok) {
        return { _tag: "Verified" };
      }

      const code = await readErrorCode(verifyRes);

      if (verifyRes.status === 404 || code === "PASSKEY_NOT_FOUND") {
        await signalUnknownCredentialSafe(rpId, encodedId);
      }

      return { _tag: "Failed" };
    } catch {
      return { _tag: "Failed" };
    }
  });

export type PasskeyRegisterOutcome =
  | { readonly _tag: "Success" }
  | { readonly _tag: "Cancelled" }
  | { readonly _tag: "Failure"; readonly failure: Failure };

export const registerPasskey = (name?: string): Effect.Effect<PasskeyRegisterOutcome> =>
  Effect.promise(async (): Promise<PasskeyRegisterOutcome> => {
    const trimmedName = name?.trim() ?? "";

    const query = trimmedName === "" ? "" : `?name=${encodeURIComponent(trimmedName)}`;

    let optionsJson: unknown;

    try {
      const optionsRes = await fetch(`/auth/passkey/generate-register-options${query}`, {
        method: "GET",
        credentials: "same-origin",
      });

      if (!optionsRes.ok) {
        if (optionsRes.status === 401) {
          return { _tag: "Failure", failure: "Unauthenticated" };
        }

        const code = await readErrorCode(optionsRes);

        if (optionsRes.status === 403 || code === "SESSION_NOT_FRESH") {
          return { _tag: "Failure", failure: "PasskeySignInAgainRequired" };
        }

        return { _tag: "Failure", failure: "Unavailable" };
      }

      optionsJson = await optionsRes.json();
    } catch {
      return { _tag: "Failure", failure: "Unavailable" };
    }

    const publicKey = parseCreationOptions(optionsJson);

    if (publicKey === null) {
      return { _tag: "Failure", failure: "Unavailable" };
    }

    const rpId = Option.match(Schema.decodeUnknownOption(CreationRpPayload)(optionsJson), {
      onNone: () => publicKey.rp.id,
      onSome: (parsed) => parsed.rp?.id ?? publicKey.rp.id,
    });

    let credential: Credential | null = null;

    try {
      credential = await navigator.credentials.create({ publicKey });
    } catch (error) {
      const errName = errorNameOf(error);

      if (errName === "InvalidStateError") {
        return { _tag: "Failure", failure: "PasskeyAlreadyExists" };
      }

      if (errName === "NotAllowedError" || errName === "AbortError") {
        return { _tag: "Cancelled" };
      }

      return { _tag: "Failure", failure: "Unavailable" };
    }

    if (!(credential instanceof PublicKeyCredential)) {
      return { _tag: "Failure", failure: "Unavailable" };
    }

    const encoded = serializeCredential(credential);

    if (encoded === null) {
      return { _tag: "Failure", failure: "Unavailable" };
    }

    const encodedId = Option.match(Schema.decodeUnknownOption(EncodedIdPayload)(encoded), {
      onNone: () => undefined,
      onSome: (parsed) => parsed.id,
    });

    try {
      const verifyRes = await fetch("/auth/passkey/verify-registration", {
        method: "POST",
        headers: { "content-type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({
          response: encoded,
          ...(trimmedName === "" ? {} : { name: trimmedName }),
        }),
      });

      if (!verifyRes.ok) {
        await signalUnknownCredentialSafe(rpId, encodedId);

        if (verifyRes.status === 401) {
          return { _tag: "Failure", failure: "Unauthenticated" };
        }

        const code = await readErrorCode(verifyRes);

        if (verifyRes.status === 403 || code === "SESSION_NOT_FRESH") {
          return { _tag: "Failure", failure: "PasskeySignInAgainRequired" };
        }

        return { _tag: "Failure", failure: "Unavailable" };
      }

      return { _tag: "Success" };
    } catch {
      await signalUnknownCredentialSafe(rpId, encodedId);

      return { _tag: "Failure", failure: "Unavailable" };
    }
  });

export type PasskeyListOutcome =
  | { readonly _tag: "Success"; readonly passkeys: readonly PasskeyItem[] }
  | { readonly _tag: "Failure"; readonly failure: Failure };

export const listUserPasskeys: Effect.Effect<PasskeyListOutcome> = Effect.promise(
  async (): Promise<PasskeyListOutcome> => {
    try {
      const response = await fetch("/auth/passkey/list-user-passkeys", {
        method: "GET",
        credentials: "same-origin",
      });

      if (!response.ok) {
        return {
          _tag: "Failure",
          failure: response.status === 401 ? "Unauthenticated" : "Unavailable",
        };
      }

      const body: unknown = await response.json();
      const decoded = Schema.decodeUnknownOption(RawPasskeyList)(body);

      if (Option.isNone(decoded)) {
        return { _tag: "Failure", failure: "Unavailable" };
      }

      return {
        _tag: "Success",
        passkeys: decoded.value.map((row) => ({
          id: row.id,
          name: row.name ?? null,
          credentialID: row.credentialID,
          deviceType: row.deviceType,
          backedUp: Boolean(row.backedUp),
          createdAt: isoStringOf(row.createdAt),
          aaguid: row.aaguid ?? null,
        })),
      };
    } catch {
      return { _tag: "Failure", failure: "Unavailable" };
    }
  },
);

export type PasskeyMutationOutcome =
  | { readonly _tag: "Success" }
  | { readonly _tag: "Failure"; readonly failure: Failure };

const postPasskeyMutation = (path: string, body: unknown): Effect.Effect<PasskeyMutationOutcome> =>
  Effect.promise(async (): Promise<PasskeyMutationOutcome> => {
    try {
      const response = await fetch(path, {
        method: "POST",
        headers: { "content-type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify(body),
      });

      if (response.ok) {
        return { _tag: "Success" };
      }

      if (response.status === 401) {
        return { _tag: "Failure", failure: "Unauthenticated" };
      }

      if (response.status === 404) {
        return { _tag: "Failure", failure: "NotFound" };
      }

      return { _tag: "Failure", failure: "Unavailable" };
    } catch {
      return { _tag: "Failure", failure: "Unavailable" };
    }
  });

export const renameUserPasskey = (id: string, name: string): Effect.Effect<PasskeyMutationOutcome> =>
  postPasskeyMutation("/auth/passkey/update-passkey", { id, name });

export const deleteUserPasskey = (id: string): Effect.Effect<PasskeyMutationOutcome> =>
  postPasskeyMutation("/auth/passkey/delete-passkey", { id });

import * as DateTime from "effect/DateTime";
import { Option, Predicate, Schema } from "effect";
import type { Html, HtmlBuilder } from "foldkit/html";
import { formatDate, message } from "../messages/locale.ts";
import { Failure } from "./api.ts";
import {
  appButton,
  badge,
  buttonClass,
  confirmDialog,
  dangerLinkButton,
  linkButton,
  panel,
  problemView,
  secondaryButtonClass,
  subSectionTitle,
  textField,
} from "./components.ts";
import type { Child } from "./components.ts";
import { aaguidProviderName, PasskeyItem } from "./passkeyClient.ts";

export const LoadedPasskeys = Schema.Union([
  Schema.TaggedStruct("Idle", {}),
  Schema.TaggedStruct("Loading", {}),
  Schema.TaggedStruct("Loaded", { passkeys: Schema.Array(PasskeyItem) }),
  Schema.TaggedStruct("Failed", { failure: Failure }),
]);

export type LoadedPasskeys = typeof LoadedPasskeys.Type;

export interface PasskeysViewState {
  readonly list: LoadedPasskeys;
  readonly supported: boolean;
  readonly busy: boolean;
  readonly notice: string | null;
  readonly failure: Failure | undefined;
  readonly editingId: string | undefined;
  readonly editingName: string;
  readonly pendingDeleteId: string | undefined;
}

export interface PasskeysViewActions<Message> {
  readonly onAdd: Message;
  readonly onStartRename: (id: string, currentName: string) => Message;
  readonly onRenameChange: (value: string) => Message;
  readonly onSaveRename: Message;
  readonly onCancelRename: Message;
  readonly onAskDelete: (id: string) => Message;
  readonly onConfirmDelete: Message;
  readonly onCancelDelete: Message;
}

export const passkeyDisplayName = (passkey: PasskeyItem): string => {
  const custom = passkey.name?.trim();

  if (custom !== undefined && custom !== "") {
    return custom;
  }

  return aaguidProviderName(passkey.aaguid) ?? message("passkeys.defaultName");
};

const passkeyMeta = (passkey: PasskeyItem): string | null => {
  if (passkey.createdAt === null) {
    return null;
  }

  return Option.match(DateTime.make(passkey.createdAt), {
    onNone: () => null,
    onSome: (instant) => message("passkeys.createdAt", { date: formatDate(instant) }),
  });
};

const passkeyRow = <Message>(
  passkey: PasskeyItem,
  state: PasskeysViewState,
  actions: PasskeysViewActions<Message>,
  h: HtmlBuilder<Message>,
): Html => {
  const displayName = passkeyDisplayName(passkey);
  const meta = passkeyMeta(passkey);
  const isEditing = state.editingId === passkey.id;
  const isDeleting = state.pendingDeleteId === passkey.id;

  return h.keyed("li")(
    passkey.id,
    [h.Class("rounded-control border border-line-soft bg-subtle/40 p-4")],
    [
      isEditing
        ? h.form(
            [h.Class("flex flex-col gap-3"), h.OnSubmit(actions.onSaveRename)],
            [
              textField(
                {
                  id: `passkey-name-${passkey.id}`,
                  label: message("passkeys.renameLabel"),
                  value: state.editingName,
                  maxLength: 64,
                  isDisabled: state.busy,
                  onInput: actions.onRenameChange,
                },
                h,
              ),
              h.div(
                [h.Class("flex flex-wrap gap-3")],
                [
                  appButton(
                    {
                      text: message("passkeys.save"),
                      type: "submit",
                      className: buttonClass,
                      isDisabled: state.busy || state.editingName.trim() === "",
                    },
                    h,
                  ),
                  appButton(
                    {
                      text: message("confirm.cancel"),
                      className: secondaryButtonClass,
                      isDisabled: state.busy,
                      onClick: actions.onCancelRename,
                    },
                    h,
                  ),
                ],
              ),
            ],
          )
        : h.div(
            [h.Class("flex flex-wrap items-center justify-between gap-3")],
            [
              h.div(
                [h.Class("min-w-0")],
                [
                  h.div(
                    [h.Class("flex flex-wrap items-center gap-2")],
                    [
                      h.span([h.Class("font-semibold text-ink")], [displayName]),
                      badge(
                        passkey.backedUp ? "primary" : "neutral",
                        [message(passkey.backedUp ? "passkeys.synced" : "passkeys.deviceBound")],
                        h,
                      ),
                    ],
                  ),
                  meta === null ? null : h.p([h.Class("mt-1 text-sm text-muted")], [meta]),
                ].filter(Predicate.isNotNull),
              ),
              h.div(
                [h.Class("flex flex-wrap items-center gap-3")],
                [
                  appButton(
                    {
                      text: message("passkeys.rename"),
                      className: linkButton,
                      isDisabled: state.busy,
                      onClick: actions.onStartRename(passkey.id, displayName),
                    },
                    h,
                  ),
                  isDeleting
                    ? null
                    : appButton(
                        {
                          text: message("passkeys.remove"),
                          className: dangerLinkButton,
                          isDisabled: state.busy,
                          onClick: actions.onAskDelete(passkey.id),
                        },
                        h,
                      ),
                ].filter(Predicate.isNotNull),
              ),
            ],
          ),
      isDeleting
        ? confirmDialog(
            {
              title: message("passkeys.confirmRemove"),
              body: message("passkeys.confirmRemoveBody", { name: displayName }),
              confirmText: message("passkeys.remove"),
              cancelText: message("confirm.cancel"),
              isBusy: state.busy,
              onConfirm: actions.onConfirmDelete,
              onCancel: actions.onCancelDelete,
            },
            h,
          )
        : null,
    ].filter(Predicate.isNotNull),
  );
};

export const passkeysView = <Message>(
  state: PasskeysViewState,
  actions: PasskeysViewActions<Message>,
  h: HtmlBuilder<Message>,
): Child => {
  const listContent: Child | null = (() => {
    switch (state.list._tag) {
      case "Idle": {
        return null;
      }

      case "Loading": {
        return h.p([h.Class("mt-4 text-sm text-muted")], [message("passkeys.loading")]);
      }

      case "Failed": {
        return problemView(state.list.failure, h);
      }

      case "Loaded": {
        if (state.list.passkeys.length === 0) {
          return h.p([h.Class("mt-4 text-sm text-muted")], [message("passkeys.empty")]);
        }

        return h.ul(
          [h.Class("mt-4 flex flex-col gap-3")],
          state.list.passkeys.map((passkey) => passkeyRow(passkey, state, actions, h)),
        );
      }
    }
  })();

  return panel(
    [
      subSectionTitle(message("passkeys.title"), h, 2),
      h.p([h.Class("mt-1 leading-relaxed text-muted")], [message("passkeys.body")]),
